text:
{
 "contract_type": "saas",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Orchard Data Ltd."],
   "quote": "by and between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Orchard Data Ltd. (\"Orchard\")"
  },
  "counterparty": {
   "value": "Orchard Data Ltd.",
   "quote": "and Orchard Data Ltd. (\"Orchard\")"
  },
  "effective_date": {
   "value": "2025-01-01",
   "quote": "made and entered into as of 1 January 2025 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 36,
   "quote": "for a period of three (3) years commencing on the Effective Date (the \"Initial Term\")"
  },
  "auto_renewal": {
   "value": true,
   "quote": "this Agreement shall renew automatically for successive additional terms of twelve months each."
  },
  "renewal_notice_days": {
   "value": 60,
   "quote": "no later than 60 days before the applicable renewal date."
  },
  "governing_law": {
   "value": "Florida",
   "quote": "shall be governed by the laws of the State of Florida."
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  },
  "payment_terms_days": {
   "value": 45,
   "quote": "Invoices are payable within 45 days after the invoice date."
  },
  "contract_value": {
   "value": 48000,
   "quote": "The subscription fee is $48,000 per year, invoiced annually in advance."
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Imogen Carter",
   "email": "imogen.carter@orchard.example",
   "title": "Managing Director",
   "party": "Orchard Data Ltd."
  }
 ],
 "risks": [
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The contract has no termination clause, so Northwind is locked into the 3-year term (about $144,000 in fees) with no stated exit right.",
   "quote": "This Agreement shall remain in force for a period of three (3) years commencing on the Effective Date (the \"Initial Term\")."
  },
  {
   "id": "evergreen_auto_renewal",
   "severity": "medium",
   "message": "The agreement renews automatically for 12-month terms unless notice is given at least 60 days before the renewal date, so a missed deadline commits Northwind to another year.",
   "quote": "this Agreement shall renew automatically for successive additional terms of twelve months each."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The agreement has no confidentiality or data protection provisions, leaving Northwind's data shared with the analytics platform unprotected by contract.",
   "quote": "This Agreement constitutes the entire agreement between the Parties and supersedes all prior discussions relating to its subject matter."
  },
  {
   "id": "undefined_terms_and_one_sided_sla",
   "severity": "low",
   "message": "The agreement uses terms such as \"Customer\", \"Provider\", \"Service\" and \"Authorized Users\" that are never defined, and the 99.9% uptime commitment has no stated remedy, which creates ambiguity and makes the SLA hard to enforce.",
   "quote": "Provider shall make the Service available with 99.9% uptime measured monthly, excluding scheduled maintenance."
  },
  {
   "id": "mutual_cap_tied_to_fees",
   "severity": "low",
   "message": "Liability for both parties is capped at 12 months of fees (about $48,000), which may be low relative to harm from a data incident, and there are no carve-outs.",
   "quote": "IN NO EVENT SHALL THE AGGREGATE LIABILITY OF EITHER PARTY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a three-year SaaS subscription between Northwind Labs, Inc. and Orchard Data Ltd. at $48,000 per year, starting 1 January 2025, governed by Florida law. It renews automatically each year unless notice is given 60 days ahead, caps liability at 12 months of fees, and has no termination-for-convenience or confidentiality terms."
}
